const LRUCache = require('./s5_cache');

describe('LRUCache', () => {
  it('should throw an error if capacity is not a positive integer', () => {
    expect(() => new LRUCache(-1)).toThrow('Capacity must be a positive integer');
    expect(() => new LRUCache(0)).toThrow('Capacity must be a positive integer');
    expect(() => new LRUCache(1.5)).toThrow('Capacity must be a positive integer');
    expect(() => new LRUCache('10')).toThrow('Capacity must be a positive integer');
  });

  it('should throw an error if ttlMs is given but not a positive integer', () => {
    const cache = new LRUCache(10);
    expect(() => cache.set('key', 'value', -1)).toThrow('ttlMs must be a positive integer');
    expect(() => cache.set('key', 'value', 0)).toThrow('ttlMs must be a positive integer');
    expect(() => cache.set('key', 'value', 1.5)).toThrow('ttlMs must be a positive integer');
    expect(() => cache.set('key', 'value', '10')).toThrow('ttlMs must be a positive integer');
  });
});

